use super::*;use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};use semio_framework_value::retained_clone::RetainedCloneGrant;
fn clock()->Option<u64>{Some(1)}fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1<<20,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096}}fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16777216,maximum_release_bytes:1048576,maximum_depth:4096}}
fn scalar_pages<T:MeshScalar+From<u16>+PartialEq+std::fmt::Debug>(items:u16){let request=super::super::tests::request(4);let mut caller=OriginalJobFixtureCaller::admit(OperationId(request.identity.operation),Generation(request.identity.generation),stock(),clock,u64::MAX,1<<20);let mut pages=RetainedMeshPages::<T>::new(items as usize,1<<20).unwrap();let mut row=0;let mut steps=0;while row<items&&steps<10000{let written=caller.turn(grant(),|cx|Ok(pages.append([T::from(row),T::from(row+1),T::from(row+2)],&mut PreparationTurn{identity:&request.identity,cx}).unwrap())).unwrap();if written{row+=1}steps+=1;}assert_eq!(pages.len(),items as usize);assert!(steps>items as usize);for index in 0..items{for axis in 0..3{assert_eq!(pages.get(index as usize,axis).unwrap(),T::from(index+axis as u16));}}pages.begin_close();for _ in 0..10000{if pages.terminal_is_empty(){break}caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{pages.close(&mut PreparationTurn{identity:&request.identity,cx}).unwrap();Ok(())})).unwrap();}assert!(pages.terminal_is_empty());assert_eq!(pages.allocated_bytes(),0);assert_eq!(pages.get(0,0).unwrap_err(),"mesh-pages-no-longer-owned");caller.retire(stock());}
#[test]fn neutral_mesh_pages_reserve_place_and_return_under_original_grants(){let fixture=semio_framework_pack_json::parse(include_str!("🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for row in fixture["cases"].as_array().unwrap(){let count=row["items"].as_u64().unwrap()as u16;if row["scalarBytes"].as_u64()==Some(8){scalar_pages::<f64>(count)}else{scalar_pages::<u32>(count)}}}
